import { useEffect, useState } from 'react'
import { obtenerAdicionesDe, obtenerCategorias, obtenerProductos } from '../../data/menu.js'
import CategoryTabs from './CategoryTabs.jsx'
import ProductCard from './ProductCard.jsx'
import ProductDetail from './ProductDetail.jsx'
import CartPanel from './CartPanel.jsx'
import { useCart } from './CartContext.jsx'
import './MenuPage.css'

export default function MenuPage() {
  const [estado, setEstado] = useState('cargando')
  const [categorias, setCategorias] = useState([])
  const [productos, setProductos] = useState([])
  const [activa, setActiva] = useState(null)
  const [seleccion, setSeleccion] = useState(null)
  const { agregar } = useCart()

  useEffect(() => {
    let vigente = true
    Promise.all([obtenerCategorias(), obtenerProductos()])
      .then(([cats, prods]) => {
        if (!vigente) return
        setCategorias(cats)
        setProductos(prods)
        setActiva(cats[0]?.id ?? null)
        setEstado('listo')
      })
      .catch(() => { if (vigente) setEstado('error') })
    return () => { vigente = false }
  }, [])

  async function elegir(producto) {
    try {
      const adiciones = await obtenerAdicionesDe(producto.id)
      setSeleccion({ producto, adiciones })
    } catch {
      setEstado('error')
    }
  }

  const categoriaActiva = categorias.find((categoria) => categoria.id === activa)
  const visibles = productos.filter((producto) => producto.categoriaId === activa)

  return (
    <main className="menu">
      <aside className="menu__lateral">
        <a className="menu__marca" href="/" aria-label="Capycoffe, inicio">Capycoffe<span>.</span></a>
        <p className="menu__introduccion">Una pausa rica empieza aquí.</p>
        {estado === 'listo' && <CategoryTabs categorias={categorias} activa={activa} onCambiar={setActiva} />}
      </aside>

      <section className="menu__contenido" aria-live="polite">
        {estado === 'cargando' && <p className="menu__aviso">Cargando el menú…</p>}
        {estado === 'error' && <p className="menu__aviso" role="alert">No pudimos cargar el menú. Intenta de nuevo más tarde.</p>}
        {estado === 'listo' && <>
          <header className="menu__encabezado">
            <p className="menu__sobrelinea">Hecho para disfrutar</p>
            <h1>{categoriaActiva?.nombre ?? 'Nuestro menú'}</h1>
            <p>Elige algo rico para acompañar tu día.</p>
          </header>
          {visibles.length === 0 ? <p className="menu__aviso">Todavía no hay productos en esta categoría.</p> :
            <div className="menu__grilla">{visibles.map((producto) => (
              <ProductCard key={producto.id} producto={producto} onElegir={elegir} />
            ))}</div>}
        </>}
      </section>

      <CartPanel />
      {seleccion && <ProductDetail
        key={seleccion.producto.id}
        producto={seleccion.producto}
        adiciones={seleccion.adiciones}
        onCerrar={() => setSeleccion(null)}
        onAgregar={(item) => { agregar(item); setSeleccion(null) }}
      />}
    </main>
  )
}
