import Badge from '../../components/ui/Badge.jsx'
import './ProductCard.css'

const formatoPesos = new Intl.NumberFormat('es-CO', {
  style: 'currency',
  currency: 'COP',
  maximumFractionDigits: 0,
})

export default function ProductCard({ producto, seleccionado, onElegir }) {
  const { nombre, precio, disponible } = producto

  return (
    <button
      type="button"
      className={`producto${disponible ? '' : ' producto--agotado'}${seleccionado ? ' producto--seleccionado' : ''}`}
      disabled={!disponible}
      aria-pressed={seleccionado}
      onClick={() => onElegir(producto)}
    >
      <span className="producto__nombre">{nombre}</span>
      <span className="producto__precio">{formatoPesos.format(precio)}</span>
      <Badge tipo={disponible ? 'ok' : 'error'}>
        {disponible ? 'Disponible' : 'Agotado'}
      </Badge>
    </button>
  )
}
