import { AuthProvider, useAuth } from './features/auth/AuthContext.jsx'
import LoginPage from './features/auth/LoginPage.jsx'
import RoleSelectPage from './features/auth/RoleSelectPage.jsx'
import SoloAdmin from './features/auth/SoloAdmin.jsx'
import StaffLayout from './features/auth/StaffLayout.jsx'
import { CartProvider } from './features/menu/CartContext.jsx'
import MenuPage from './features/menu/MenuPage.jsx'
import OrdersPage from './features/orders/OrdersPage.jsx'
import InventoryPage from './features/inventory/InventoryPage.jsx'
import TeamPage from './features/team/TeamPage.jsx'
import { Navigate, NavigationProvider, useNavigation } from './lib/navigation.jsx'

function Paginas() {
  const { path } = useNavigation()
  const { usuario, cargando } = useAuth()

  if (path === '/') return <CartProvider><MenuPage /></CartProvider>
  if (path.startsWith('/staff') && cargando) return null
  if (path === '/staff') return <RoleSelectPage />
  if (/^\/staff\/ingresar\/[^/]+\/?$/.test(path)) return <LoginPage />

  const paginas = {
    '/staff/pedidos': <OrdersPage />,
    '/staff/inventario': <SoloAdmin><InventoryPage /></SoloAdmin>,
    '/staff/equipo': <SoloAdmin><TeamPage /></SoloAdmin>,
  }
  const pagina = paginas[path]
  if (pagina) return <StaffLayout>{pagina}</StaffLayout>
  if (path.startsWith('/staff/') && !usuario) return <Navigate to="/staff" replace />
  return <Navigate to="/" replace />
}

export default function App() {
  return <NavigationProvider><AuthProvider><Paginas /></AuthProvider></NavigationProvider>
}
