import Button from '../../components/ui/Button.jsx'

export default function CategoryTabs({ categorias, activa, onCambiar }) {
  return (
    <nav className="categorias" aria-label="Categorías del menú">
      {categorias.map((categoria) => (
        <Button
          key={categoria.id}
          bloque
          variante={categoria.id === activa ? 'primario' : 'secundario'}
          aria-pressed={categoria.id === activa}
          onClick={() => onCambiar(categoria.id)}
        >
          {categoria.nombre}
        </Button>
      ))}
    </nav>
  )
}
